const $=s=>document.querySelector(s);let loaded;try{loaded=loadWorkspace(localStorage);}catch{loaded={workspace:{version:2,activeId:'original',boards:[{id:'original',name:'我的白板',state:initialState()}]},error:true};}let workspace=loaded.workspace;let state=workspace.boards.find(b=>b.id===workspace.activeId).state;const loadError=loaded.error;
const objects=new Map(),folderObjects=new Map(),stickerObjects=new Map();let editing=null,activeFolder=null,drag=null,busy=false,animations=[],toastTimer;
const floating=new Map();let floatPage=0,opening=false;
const scrim=new THREE.Mesh(new THREE.PlaneGeometry(200,200),new THREE.MeshBasicMaterial({color:'#111216',transparent:true,opacity:0,depthWrite:false}));scrim.position.set(0,3,.83);scrim.visible=false;model.add(scrim);
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),2200);}
function save(){try{persistWorkspace(localStorage,workspace);$('#save-status').textContent='已保存到本机';$('#editor-status').textContent='已自动保存';$('#save-indicator').dataset.state='saved';$('#save-indicator').title='已保存到本机';return true;}catch{$('#save-status').textContent='保存失败 · 请导出备份';$('#editor-status').textContent='保存失败，请导出备份';$('#save-indicator').dataset.state='error';$('#save-indicator').title='保存失败，请导出备份';toast('存储空间不足或不可用，请导出备份');return false;}}
let draftTimer,draftDirty=false,deletedDraft=false;
function queueDraft(){if(!editing)return;draftDirty=true;$('#editor-status').textContent='正在保存…';$('#save-indicator').dataset.state='pending';clearTimeout(draftTimer);draftTimer=setTimeout(flushDraft,350);}
function flushDraft(){clearTimeout(draftTimer);if(!editing||!draftDirty||deletedDraft)return;const draft={...editing,title:$('#note-title').value,body:$('#note-body').value,color:$('#note-color').value,folderId:$('#note-folder').value||null};if(draft.kind==='drawing')draft.drawing=$('#drawing').toDataURL('image/png');editing=upsertDraft(state,draft);if(save())draftDirty=false;renderLists();}
