canvas.addEventListener('pointerup',e=>endDrag(e),true);canvas.addEventListener('pointercancel',e=>endDrag(e,true),true);
function openEditor(n=null,kind='note'){if(busy)return;draftDirty=false;deletedDraft=false;$('#editor-status').textContent=n?'已自动保存':'输入即自动保存';editing=n?{...n}:{id:uuid(),title:'',body:'',color:'#eeeef0',kind,x:controls.target.x+(Math.random()-.5)*.5,y:controls.target.y,rotation:-.035,folderId:activeFolder};$('#editor-label').textContent=n?'编辑笔记':kind==='drawing'?'画下一个念头':'写一张便签';$('#note-title').value=editing.title;$('#note-body').value=editing.body;$('#note-color').value=editing.color;$('#delete-note').hidden=!n;$('#take-note').hidden=!n?.folderId;$('#note-folder').replaceChildren(new Option('白板',''),...state.folders.map(f=>new Option(f.name,f.id)));$('#note-folder').value=editing.folderId??'';$('#drawing-wrap').hidden=editing.kind!=='drawing';$('#note-body').hidden=editing.kind==='drawing';drawCtx.fillStyle='#f0f0ec';drawCtx.fillRect(0,0,720,480);if(editing.drawing){const img=new Image();const drawingId=editing.id;img.onload=()=>{if(editing?.id===drawingId&&$('#editor').open){drawCtx.drawImage(img,0,0,720,480);}};img.src=editing.drawing;}$('#editor').showModal();$('#note-title').focus();}
$('#new-note').onclick=()=>openEditor();$('#new-drawing').onclick=()=>openEditor(null,'drawing');
$('#note-form').onsubmit=e=>{e.preventDefault();unlock();draftDirty=true;flushDraft();if(draftDirty)return;const item=editing;$('#editor').close();playSound(item.folderId?'snap':'place');};
$('#delete-note').onclick=()=>{clearTimeout(draftTimer);deletedDraft=true;draftDirty=false;state.notes=state.notes.filter(n=>n.id!==editing.id);editing=null;$('#editor').close();syncScene();save();toast('笔记已删除');};
function clearFloating(){for(const m of floating.values())disposePaper(m);floating.clear();$('#float-items').replaceChildren();}
function showFloating(id,instant=false){
 clearFloating();activeFolder=id;document.body.classList.add('folder-open');$('#library').hidden=true;$('#float-bar').hidden=false;scrim.visible=true;scrim.material.opacity=.76;controls.enabled=false;
 const f=state.folders.find(f=>f.id===id),all=state.notes.filter(n=>n.folderId===id);if(!f)return;
 const perPage=6,pages=Math.max(1,Math.ceil(all.length/perPage));floatPage=Math.min(floatPage,pages-1);const notes=all.slice(floatPage*perPage,(floatPage+1)*perPage);
 $('#float-title').textContent=f.name;$('#float-page').textContent=pages>1?`${floatPage+1}/${pages}`:'';$('#float-prev').hidden=$('#float-next').hidden=pages===1;$('#float-prev').disabled=floatPage===0;$('#float-next').disabled=floatPage===pages-1;
 if(!notes.length)toast('空口袋 · 点 ＋ 放入第一张笔记');
 const narrow=host.clientWidth<650,cols=narrow?2:3,rows=Math.ceil(notes.length/cols),spacing=narrow?1.65:1.7;
 notes.forEach((n,i)=>{const row=Math.floor(i/cols),rowSize=Math.min(cols,notes.length-row*cols);const x=(i%cols-(rowSize-1)/2)*spacing,y=3.65+((rows-1)/2-row)*1.95;const {width,height}=noteSize(n);const m=paper(width,height,f.x,f.y+.4,.45,n.color,c=>noteTexture(n,c),0,0,model,true);m.userData={id:n.id,type:'float',restY:y,phase:i*.8,restRotation:(i%3-1)*.035};floating.set(n.id,m);const from=m.position.clone(),to=new THREE.Vector3(x,y,1.6);m.scale.setScalar(.35);animate(instant?1:650,t=>{if(!floating.has(n.id))return;const e=1-Math.pow(1-t,3);m.position.lerpVectors(from,to,e);m.position.z+=Math.sin(t*Math.PI)*.3;m.scale.setScalar(.35+.65*e);m.rotation.z=m.userData.restRotation*e;});$('#float-items').append(button(n.title,()=>openEditor(n)));});
 const g=folderObjects.get(id);const cover=g?.getObjectByName('pocketCover');if(cover)animate(400,t=>{cover.rotation.x=.055+.18*t;});
 opening=true;animate(instant?1:700,()=>{},()=>opening=false);
 const distance=narrow?(rows>=3?14:11.3):11.2;go([0,3.65,distance],[0,3.65,.8]);
}
function openFolder(id){if(busy)return;if(activeFolder===id){closeFloating();return;}floatPage=0;playSound('lift');showFloating(id);}
function closeFloating(){if(!activeFolder)return;const id=activeFolder,f=state.folders.find(f=>f.id===id);activeFolder=null;$('#float-bar').hidden=true;$('#float-items').replaceChildren();document.body.classList.remove('folder-open');controls.enabled=true;opening=false;const old=[...floating.values()];floating.clear();old.forEach(m=>{const from=m.position.clone();animate(320,t=>{const e=t*t;m.position.lerpVectors(from,new THREE.Vector3(f?.x??0,(f?.y??3.5)+.4,.5),e);m.scale.setScalar(1-e*.7);},()=>disposePaper(m));});animate(320,t=>scrim.material.opacity=.76*(1-t),()=>{if(!activeFolder)scrim.visible=false;});const cover=folderObjects.get(id)?.getObjectByName('pocketCover');if(cover)animate(300,t=>cover.rotation.x=.235-.18*t);resetView();playSound('place');}
$('#close-float').onclick=closeFloating;$('#float-prev').onclick=()=>{floatPage--;showFloating(activeFolder);};$('#float-next').onclick=()=>{floatPage++;showFloating(activeFolder);};$('#float-add').onclick=()=>openEditor();$('#float-sticker').onclick=()=>openSticker(activeFolder);
$('#library-toggle').onclick=()=>$('#library').hidden=!$('#library').hidden;
$('#take-note').onclick=()=>{const n=state.notes.find(n=>n.id===editing.id);if(!n)return;flushDraft();const current=state.notes.find(item=>item.id===n.id);current.folderId=null;current.x=.25;current.y=3.55;draftDirty=false;editing=null;$('#editor').close();closeFloating();syncScene();save();playSound('lift');};
$('#new-folder').onclick=()=>{$('#folder-name').value='';$('#name-dialog').showModal();};$('#folder-form').onsubmit=e=>{e.preventDefault();const name=$('#folder-name').value.trim();if(!name)return;if(state.folders.length>=8){toast('白板最多放 8 个文件夹');return;}state.folders.push({id:uuid(),name,x:controls.target.x+(state.folders.length%2?.8:-.8),y:controls.target.y});$('#name-dialog').close();syncScene();save();playSound('place');toast('文件夹已放上白板，可拖动摆放');};
$('#delete-folder').onclick=()=>{const id=activeFolder;closeFloating();removeFolder(state,id);syncScene();save();toast('文件夹已移除，笔记留在白板');};
const openSticker=setupStickerStudio({getState:()=>state,onApply:({id,image,folderId})=>{let item=state.stickers.find(s=>s.id===id);const previousFolder=item?.folderId??null;if(!item){item={id:uuid(),x:.65,y:3.35};state.stickers.push(item);}item.type='custom';item.image=image;attachSticker(state,item.id,folderId,previousFolder===folderId?item.x:folderId?0:.65,previousFolder===folderId?item.y:folderId?-.25:3.35);if(activeFolder)closeFloating();syncScene();save();playSound('place');const m=stickerObjects.get(item.id),targetZ=m.position.z;animate(300,t=>{m.position.z=targetZ+.25*Math.pow(1-t,3);m.rotation.x=Math.sin(t*Math.PI)*.2;});},onDelete:id=>{state.stickers=state.stickers.filter(s=>s.id!==id);syncScene();save();}});
$('#new-sticker').onclick=()=>openSticker(activeFolder);
$('#front').onclick=()=>{resetView();$('#front').classList.add('selected');$('#angle').classList.remove('selected');};$('#angle').onclick=()=>{resetView(true);$('#angle').classList.add('selected');$('#front').classList.remove('selected');};
function preferences(){setSound(state.settings.sound);setWind(state.settings.wind);$('#sound').setAttribute('aria-pressed',state.settings.sound);$('#wind').setAttribute('aria-pressed',state.settings.wind);}
$('#sound').onclick=()=>{state.settings.sound=!state.settings.sound;preferences();unlock();save();if(state.settings.sound)playSound('snap');};$('#wind').onclick=()=>{state.settings.wind=!state.settings.wind;preferences();save();};
$('#demo').onclick=()=>{if(busy)return;unlock();if(!state.folders.length){toast('先创建一个文件夹');return;}let n=state.notes.find(n=>!n.folderId);if(!n){n={id:uuid(),title:'灵感归位',body:'啪嚓。\n每个念头，都有自己的位置。',color:'#eeeef0',kind:'note',x:.5,y:4,rotation:-.04,folderId:null};state.notes.push(n);buildNote(n);}snap(n.id,state.folders[0].id);};
$('#backup').onclick=()=>{flushDraft();if(window.webkit?.messageHandlers?.exportBackup){window.webkit.messageHandlers.exportBackup.postMessage({text:JSON.stringify(workspace,null,2)});return;}const a=document.createElement('a'),url=URL.createObjectURL(new Blob([JSON.stringify(workspace,null,2)],{type:'application/json'}));a.href=url;a.download=`paperroom-${new Date().toISOString().slice(0,10)}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
document.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>document.getElementById(b.dataset.close).close());document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!document.querySelector('dialog[open]'))closeFloating();if(e.key.toLowerCase()==='n'&&!e.ctrlKey&&!e.metaKey&&!document.querySelector('dialog[open]')&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)){e.preventDefault();openEditor();}});
const drawCanvas=$('#drawing'),drawCtx=drawCanvas.getContext('2d');let drawing=false;function dp(e){const r=drawCanvas.getBoundingClientRect();return [(e.clientX-r.left)*720/r.width,(e.clientY-r.top)*480/r.height];}drawCanvas.onpointerdown=e=>{drawing=true;drawCanvas.setPointerCapture(e.pointerId);drawCtx.beginPath();drawCtx.moveTo(...dp(e));drawCtx.strokeStyle='#101114';drawCtx.lineWidth=5;drawCtx.lineCap='round';drawCtx.lineJoin='round';};drawCanvas.onpointermove=e=>{if(drawing){drawCtx.lineTo(...dp(e));drawCtx.stroke();queueDraft();}};drawCanvas.onpointerup=drawCanvas.onpointercancel=()=>{drawing=false;queueDraft();};$('#clear-drawing').onclick=()=>{drawCtx.fillStyle='#f0f0ec';drawCtx.fillRect(0,0,720,480);queueDraft();};
function renderBoards(){const select=$('#board-select');select.replaceChildren(...workspace.boards.map(b=>new Option(b.name,b.id)));select.value=workspace.activeId;}
function switchBoard(id){if(busy||drag||opening||animations.length){renderBoards();toast('请等当前动作完成');return false;}flushDraft();if(draftDirty||!save()){renderBoards();return false;}const next=workspace.boards.find(b=>b.id===id);if(!next)return false;clearFloating();activeFolder=null;scrim.visible=false;scrim.material.opacity=0;document.body.classList.remove('folder-open');$('#float-bar').hidden=true;$('#library').hidden=true;workspace.activeId=id;state=next.state;controls.enabled=true;preferences();syncScene();resetView();renderBoards();save();return true;}
$('#board-select').onchange=e=>switchBoard(e.target.value);
$('#new-board').onclick=()=>{$('#board-name').value='';$('#board-dialog').showModal();$('#board-name').focus();};
$('#board-form').onsubmit=e=>{e.preventDefault();if(busy||drag||opening||animations.length){toast('请等当前动作完成');return;}flushDraft();if(draftDirty||!save())return;try{const next=addBoard(workspace,$('#board-name').value,uuid());persistWorkspace(localStorage,next);workspace=next;state=workspace.boards.find(b=>b.id===workspace.activeId).state;clearFloating();activeFolder=null;scrim.visible=false;document.body.classList.remove('folder-open');$('#float-bar').hidden=true;controls.enabled=true;preferences();syncScene();resetView();renderBoards();$('#board-dialog').close();toast('新白板已创建');}catch{toast('创建失败，请检查名称或存储空间');}};
renderBoards();setupLanyard({getWind:()=>state.settings.wind});preferences();syncScene();if(loadError)toast('原有保存无法读取，请先保留备份');if(loaded.recovered)toast('已从本机备份恢复笔记');
const context=document.modelContext;if(context?.registerTool){const lifecycle=new AbortController();addEventListener('pagehide',()=>lifecycle.abort(),{once:true});for(const tool of [{name:'list_notes',description:'读取此白板的笔记与文件夹',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute:()=>({notes:state.notes.map(({drawing,...n})=>n),folders:state.folders})},{name:'create_note',description:'创建并保存一张白板笔记',inputSchema:{type:'object',properties:{title:{type:'string',maxLength:80},body:{type:'string',maxLength:10000}},required:['title'],additionalProperties:false},execute:input=>{if(typeof input.title!=='string'||!input.title.trim()||input.title.length>80||(input.body!==undefined&&(typeof input.body!=='string'||input.body.length>10000)))throw Error('无效笔记');const n={id:uuid(),title:input.title.trim(),body:input.body??'',kind:'note',color:'#eeeef0',x:0,y:3.6,rotation:0,folderId:null};state.notes.push(n);syncScene();save();return {id:n.id};}}])try{Promise.resolve(context.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{});}catch{}}

portraitReady.then(ready=>{if(!ready)return;for(const n of state.notes){if(n.kind!=='portrait')continue;for(const m of [objects.get(n.id),floating.get(n.id)]){if(!m)continue;const c=m.material.map.image.getContext('2d');c.fillStyle=n.color;c.fillRect(0,0,c.canvas.width,c.canvas.height);noteTexture(n,c);m.material.map.needsUpdate=true;}}});
